#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str


def solve(S: str):
    N = int(len(S))
    ans = YES

    for i in range(N//2):
        if S[i] != S[-1 - i]:
            ans = NO
            break

    S_left, S_right = S[:N//2], S[N//2 + 1:]

    for i in range(N//2//2):
        if S_left[i] != S_left[-1 - i]:
            ans = NO
            break
        if S_right[i] != S_right[-1 - i]:
            ans = NO
            break
    print(ans)


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

if __name__ == '__main__':
    main()
